// Formatted output (stdio.h)
int val = 42;
printf("The answer is %d.\n", val);
printf("Float: %.2f | String: %s\n", 3.14, "OK");

// Simple string output (adds newline)
puts("Output String.");

// Single character output
char c = 'A';
putchar(c);
putchar('\n');

// Stream control (stdout vs stderr)
fprintf(stdout, "Standard message.\n");
fprintf(stderr, "Debugging error.\n");
